/**
 * Jinx Alchemist + Widow: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Alchemist
 * Wiki: https://wiki.bloodontheclocktower.com/Widow
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData, committedCharacters } from '#lib/core/testing/committed-data.ts';
import { abilityState } from '#lib/core/rules/abilities/ability.ts';
import { hasAbilityOf } from '#lib/core/rules/abilities/gained-abilities.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes/jinx-pairs.ts';
import { jinxGuessers } from '#lib/core/rules/jinxes/jinx-effects.ts';
import { nightStepAlerts } from '#lib/core/rules/night/night-alerts.ts';
import { alchemistAs, bagNotes } from './alchemist.test-support.ts';

describe('Alchemist + Widow jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'alchemist', 'widow');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('alchemist')?.name).toBe('Alchemist');
		expect(data.byId.get('widow')?.name).toBe('Widow');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['alchemist', 'widow'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['alchemist'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['widow'])).not.toContain(jinx);
	});

	it("is data in the Alchemist's rules", () => {
		// Wiki: "An Alchemist-Widow has no Widow ability & a Widow is in play. After each execution, a living Alchemist-Widow may publicly guess a living player as the Widow. If correct, the Demon must choose the Widow tonight."
		expect(jinxRulesBetween('alchemist', 'widow', committedCharacters())).toEqual({
			impairs: { kind: 'no-ability', when: ['has-partner-ability'] },
			partnerInPlay: {},
			guessesPartner: { when: ['has-partner-ability', 'self-alive', 'after-execution'] }
		});
	});

	// Seat 0 the Alchemist-Widow, seat 2 the real Widow.
	const base = alchemistAs('widow', ['chef', 'widow', 'imp', 'empath']);
	const guesses = (s: typeof base) => jinxGuessers(s.game, s.characters);
	const alerts = (s: typeof base) =>
		nightStepAlerts(s.game, 'imp', s.characters).filter((a) => a.kind === 'guessed');

	describe('an Alchemist-Widow has no Widow ability, and a Widow is in play', () => {
		it('notes the real Widow at setup when the Alchemist is chosen', () => {
			// Wiki: "a Widow is in play"
			const note =
				'Alchemist with the Widow ability: the Widow is in play too, and the Alchemist has no ability.';
			expect(bagNotes('widow')).toContain(note);
			expect(bagNotes('widow', false)).not.toContain(note);
		});

		it('leaves the Alchemist-Widow with no ability, and the real Widow with theirs', () => {
			// Wiki: "An Alchemist-Widow has no Widow ability"
			const state = abilityState(base.game, base.seat(0), base.characters);
			expect(state.works).toBe(false);
			expect(state.impairments).toMatchObject([
				{ reason: 'no-ability', source: { characterId: 'widow' } }
			]);
			expect(hasAbilityOf(base.game, base.seat(0), 'widow', base.characters)).toBe(false);
			expect(hasAbilityOf(base.game, base.seat(2), 'widow', base.characters)).toBe(true);
		});
	});

	describe('after each execution, a living Alchemist-Widow may guess the Widow', () => {
		it('lets them guess once someone has been executed today', () => {
			// Wiki: "After each execution, a living Alchemist-Widow may publicly guess a living player as the Widow."
			expect(guesses(base)).toEqual([]);
			const s = base.execute('chef');
			expect(guesses(s)).toEqual([
				{ seatId: s.seat(0), owner: 'alchemist', partner: 'widow', partnerSeats: [s.seat(2)] }
			]);
		});

		it('says at the Demon step that a right guess makes the Demon choose the Widow', () => {
			// Wiki: "If correct, the Demon must choose the Widow tonight."
			const s = base.execute('chef');
			expect(alerts(s)).toMatchObject([
				{ kind: 'guessed', seatId: s.seat(0), partner: 'widow', works: true }
			]);
			expect(alerts(base)).toEqual([]);
		});

		it('gives a dead Alchemist-Widow no guess, nor one with no living Widow', () => {
			// Wiki: "a living Alchemist-Widow may publicly guess a living player as the Widow"
			expect(guesses(base.dies(0).execute('chef'))).toEqual([]);
			expect(guesses(base.dies(2).execute('chef'))).toEqual([]);
		});
	});
});
